const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const source = fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8');
let checks = 0;
function test(name, fn) { fn(); checks += 1; console.log(`✓ ${name}`); }
function session(saved = new Map(), storageFails = false) {
  const handlers = {};
  const page = { innerHTML:'', insertAdjacentHTML(_p,markup){this.innerHTML+=markup;} };
  const document = { querySelector(s){return s==='#app'?page:null;}, querySelectorAll(){return[];}, addEventListener(k,fn){handlers[k]=fn;} };
  const context = vm.createContext({document,localStorage:{getItem:k=>saved.get(k)||null,setItem(k,v){if(storageFails)throw Error('Storage unavailable');saved.set(k,v);}},window:{scrollTo(){}},structuredClone,Date});
  vm.runInContext(source,context);
  return {page,saved,run(code){return vm.runInContext(code,context);},state(){return this.run('state');},click(action,extra={}){handlers.click({target:{closest(s){return s==='[data-action]'?{dataset:{action,...extra}}:null;}}});},
    input(field,value,update=false){this.field(update?{updateField:field}:{field},value);},
    field(dataset,value){const el={dataset,value,type:typeof value==='boolean'?'checkbox':'text',checked:value};for(const name of ['input','change'])handlers[name]({target:{closest(){return el;}}});},
    edit(id,field,value,update=false){this.field({noteField:field,id,update:String(update)},value);},
    key(key){handlers.keydown({key,preventDefault(){}});},
    reload(){return session(saved,storageFails);}
  };
}
function sampleSession(branch='feedback') {const s=session();s.click('start-sample');s.click('sample-question');if(branch!=='feedback')s.click('sample-choice',{branch});s.click('sample-answer');s.click('intro-next');return s;}
function complete() {const s=sampleSession();for(const id of ['E1','E2','E3','E4'])s.click('toggle-note',{id,status:'confirmed'});s.click('confirm-bottom');s.click('confirm-unknown');s.click('review-next');s.click('stance',{stance:'investigate'});s.click('save-action');return s;}
function guidanceCard(s){return s.run("comparisonRows().find(row=>row.title==='指导与反馈')");}

test('两种预置回答与自定义条件产生对应草稿，同义语序不改变反馈分支',()=>{
 const a=sampleSession();assert.equal(a.state().bottom.A,'pass');
 const b=sampleSession('ownership');assert.equal(b.state().bottom.A,'unknown');assert.match(b.state().unknown.text,/独立负责/);assert.doesNotMatch(b.state().actionDraft.text,/代码评审安排/);
 const c=session();c.click('start-sample');c.click('sample-question');c.input('bottom.rule','每周至少一次代码评审');c.click('sample-answer');assert.equal(c.state().sampleBranch,'feedback');assert.equal(c.state().bottom.A,'pass');
 const d=session();d.click('start-sample');d.click('sample-question');d.click('sample-choice',{branch:'custom'});d.input('bottom.rule','通勤不超过半小时');d.click('sample-answer');assert.equal(d.state().bottom.A,'unknown');assert.match(d.state().unknown.text,/通勤/);
});
test('首次梳理只确认一个未知，也能以验证行动完成',()=>{
 const s=session();s.click('start-manual');s.input('optionA','留下');s.input('optionB','去外地');s.click('intro-next');s.input('unknown.text','实际通勤多长？');s.click('confirm-unknown');s.click('review-next');assert.equal(s.state().view,'result');s.click('stance',{stance:'investigate'});s.input('actionDraft.text','实地体验一次通勤');s.click('save-action');assert.ok(s.state().firstCompletedAt);
});
