test('旧版本记录迁移后保留正文与行动，存储失败时不宣称已经保存',()=>{
 const saved=new Map([['decision-copilot:redcowork-prototype:v1',JSON.stringify({view:'result',notes:[{id:'a',side:'A',topic:'指导安排',text:'用户修改过的正文',status:'confirmed'}],actions:[{stance:'A',text:'旧行动',version:1}],actionDraft:{text:'尚未完成的行动'},firstCompletedAt:'2026-09-30',version:1})]]);
 const s=session(saved);assert.equal(s.state().notes[0].text,'用户修改过的正文');assert.equal(s.state().notes[0].topic,'指导与反馈');assert.match(s.page.innerHTML,/尚未完成的行动/);
 const broken=session(new Map(),true);broken.click('start-manual');assert.match(broken.page.innerHTML,/刷新后可能丢失/);assert.doesNotMatch(broken.page.innerHTML,/已暂存在/);
 const legacySample=new Map([['decision-copilot:redcowork-prototype:v1',JSON.stringify({mode:'sample',view:'intro',notes:[],introRevealed:true,sampleAnswer:'通勤半小时以内',bottom:{rule:'通勤半小时以内',A:'unknown',B:'unknown'},optionA:'A',optionB:'B'})]]);const legacy=session(legacySample);assert.equal(legacy.state().sampleBranch,'custom');assert.match(legacy.page.innerHTML,/不足以判断这项新条件/);
});
