function pairingSession(){const s=complete();s.run("state.notes.find(n=>n.id==='E1').topic='其它重要信息';persist();render();");return s;}
function pairingKeyboard(s){s.run(`let returnedFocus=0,lastScroll=null;const pairTrigger={dataset:{action:'pair-information',id:'E1'},focus(){returnedFocus++;}},fakeDialog={focus(){},querySelectorAll(){return[];}};window.scrollY=410;window.scrollTo=arg=>{lastScroll=arg.top;};document.querySelector=selector=>selector==='#app'?app:selector==='[role="dialog"]'&&ui.pairComparison?fakeDialog:selector==='.confirm-modal'&&ui.pairComparison?fakeDialog:selector==='[data-action="pair-information"][data-id="E1"]'?pairTrigger:null;`);}
test('Escape 与稍后再分均清除空配对更新，回到结果并恢复入口焦点和位置',()=>{
 for(const escape of [true,false]){let s=pairingSession();pairingKeyboard(s);s.click('pair-information',{id:'E1'});assert.ok(s.state().updateDraft);if(escape)s.key('Escape');else s.click('cancel-pair');assert.equal(s.state().updateDraft,null);assert.equal(s.state().view,'result');assert.equal(s.run('ui.pairComparison'),null);assert.equal(s.run('returnedFocus'),1);assert.equal(s.run('lastScroll'),410);s=s.reload();assert.equal(s.state().updateDraft,null);s.click('home');s.click('start-sample');assert.equal(s.state().view,'result');}
});
test('取消配对保留已有更新与未加入的材料，不清除有内容的临时草稿',()=>{
 const existing=pairingSession();existing.click('enter-update');existing.input('context','已有更新',true);existing.input('newText','还没加入的信息',true);pairingKeyboard(existing);existing.click('pair-information',{id:'E1'});existing.key('Escape');assert.ok(existing.state().updateDraft);assert.equal(existing.state().updateDraft.context,'已有更新');assert.equal(existing.state().updateDraft.newText,'还没加入的信息');assert.equal(existing.state().view,'update');const created=pairingSession();pairingKeyboard(created);created.click('pair-information',{id:'E1'});created.input('newText','需要保留的输入',true);created.key('Escape');assert.ok(created.state().updateDraft);assert.equal(created.state().updateDraft.newText,'需要保留的输入');
});

